@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    PageRangeRequest that = (PageRangeRequest) o;
    return from == that.from && to == that.to;
}
